const OVERVIEW_ROUTES = `<section class="mv"><h2>Choose a route</h2><p class="body-text"><a href="catalog.html">Open the evidence catalog</a> · <a href="demonstrations.html">See recorded workflows</a> · <a href="analytics/portfolio-source-inventory.html">Inspect the source inventory</a> · <a href="private-practice.html#private-system-index">Review controlled-private boundary pages</a> · <a href="hire.html">Hire or collaborate</a></p></section>`;

await writeFile(
  resolve(root, "catalog.html"),
  `${CATALOG_HEAD}<main id="main">${catalogMain}</main></body></html>\n`,
  "utf8",
);
await writeFile(
  resolve(root, "overview.html"),
  `${OVERVIEW_HEAD}<main id="main">${OVERVIEW_ROUTES}${overviewMain}</main></body></html>\n`,
  "utf8",
);

// Products whose route is the generated long-form record. Every other product
// links to a hand-written page this script must not touch.
const RECORD_PAGES = [
  "accountable-surface",
  "behavior-transform",
  "bulletin",
  "elder-enb",
  "enb-runtime-core",
  "mneme",
  "plexus",
  "relay",
  "skyrimbridge",
  "studio-engine",
  "telos",
  "truth-enb",
];

// Social cards are keyed by record id in the same object the site ships to the
// browser, so a card and its page cannot describe different products.
const cardSource = await readFile(resolve(root, "img", "og", "cards-data.js"), "utf8");
const cardById = new Map(
  Object.entries(
    JSON.parse(cardSource.slice(cardSource.indexOf("{"), cardSource.lastIndexOf("}") + 1)),
  ),
);
const recordContext = {
  cardById,
  registry,
  systemById: new Map(registry.systems.map((system) => [system.id, system])),
  domainById: new Map(registry.domains.map((domain) => [domain.id, domain])),
};

for (const id of RECORD_PAGES) {
  const system = recordContext.systemById.get(id);
  if (!system) throw new Error(`${id}: RECORD_PAGES names a record the registry does not hold`);
  await writeFile(resolve(root, system.href), renderRecordPage(system, recordContext), "utf8");
}

console.log(
  `catalog.html: ${registry.systems.length} records across ${registry.domains.length} domains`,
);
console.log(`overview.html: ${publicSystems.length} public products`);
console.log(`record pages: ${RECORD_PAGES.length}`);
